import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uv, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const root = new Group();
  const timelines = [];
  const disposables = [];

  // ===== PANEL BACKGROUND =====
  const panelGeom = new PlaneGeometry(3.4, 1.9);
  disposables.push(panelGeom);

  const panelMaterial = new MeshStandardNodeMaterial();
  disposables.push(panelMaterial);

  // Vertical gradient: #1a1a22 (top, v=1) → #111116 (bottom, v=0)
  const gradColor = mix(color(0x111116), color(0x1a1a22), uv().y);
  panelMaterial.colorNode = gradColor;
  panelMaterial.roughness = 0.6;
  panelMaterial.metalness = 0.2;
  panelMaterial.clearcoat = 0.1;
  panelMaterial.transparent = true;

  const panel = new Mesh(panelGeom, panelMaterial);
  root.add(panel);

  // ===== QUOTATION MARK =====
  // 0.62 units tall, #ff2a38, extruded appearance at z=0.04
  const quoteMark = ctx.fontAtlas.createText('"', {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });
  quoteMark.position.set(-1.2, 0.45, 0.04);
  quoteMark.scale.set(1.04, 1.04, 1.04);
  root.add(quoteMark);

  // ===== QUOTE TEXT =====
  const quoteText = ctx.fontAtlas.createText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 240
    }
  );
  quoteText.position.set(-1.2, 0.2, 0.03);
  root.add(quoteText);

  // ===== ACCENT RULE =====
  // 0.2w × 0.02h decorative rule in #ff2a38, emissive 1.4
  const ruleGeom = new PlaneGeometry(0.2, 0.02);
  disposables.push(ruleGeom);

  const ruleMaterial = new MeshStandardNodeMaterial();
  disposables.push(ruleMaterial);
  ruleMaterial.color.set(0xff2a38);
  ruleMaterial.emissive.set(0xff2a38);
  ruleMaterial.emissiveIntensity = 1.4;
  ruleMaterial.transparent = true;

  const rule = new Mesh(ruleGeom, ruleMaterial);
  rule.position.set(-1.35, -0.05, 0.03);
  root.add(rule);

  // ===== ATTRIBUTION =====
  const attribution = ctx.fontAtlas.createText('M. OKAFOR', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.04
  });
  attribution.position.set(-0.9, -0.05, 0.03);
  root.add(attribution);

  // ===== CAPTION =====
  const caption = ctx.fontAtlas.createText('COLLECTOR SINCE 2019', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.08
  });
  caption.position.set(-1.2, -0.2, 0.03);
  root.add(caption);

  // ===== ANIMATION =====
  const timeline = gsap.timeline();
  timelines.push(timeline);

  // Initial state
  root.position.y = 0.2;
  panelMaterial.opacity = 0;
  ruleMaterial.opacity = 0;

  // Fade-up: panel moves from y=0.2 to y=0, opacity 0→1 (500ms)
  timeline.to(
    root.position,
    { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );

  timeline.to(
    panelMaterial,
    { opacity: 1 },
    { duration: 0.5 },
    0
  );

  timeline.to(
    ruleMaterial,
    { opacity: 1 },
    { duration: 0.5 },
    0
  );

  // Quote mark settle: scale 1.04→1.0 (900ms, starting at 500ms offset)
  timeline.to(
    quoteMark.scale,
    { x: 1, y: 1, z: 1 },
    { duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' },
    0.5
  );

  // ===== CLEANUP =====
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => item.dispose?.());

    const disposeTree = (obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
      obj.children?.forEach(disposeTree);
    };

    [quoteMark, quoteText, attribution, caption].forEach(disposeTree);
  };

  return root;
}
